package com.hartens.optimizer;
import android.content.SharedPreferences;
import java.util.Locale;

/** Fixed allowlist only. No root, no arbitrary shell input, no global background process limit. */
final class Optimizer {
 static final String[] ANIM = {"window_animation_scale","transition_animation_scale","animator_duration_scale"};
 static final String GAMES="ru.yandex.games", BUGS="com.yandex.tv.bugreportsender", ADID="com.yandex.android.advid";
 private final AdbClient adb;
 AdbClient adbForDiagnostics(){return adb;}
 private final SharedPreferences prefs;
 private final String scope;
 Optimizer(AdbClient adb, SharedPreferences prefs, String ip){this.adb=adb;this.prefs=prefs;this.scope="host_"+ip+"_";}
 private String p(String k){return scope+k;}
 private String shell(String cmd)throws Exception {return adb.shell(cmd).trim();}
 private void guard()throws Exception {String model=shell("getprop ro.product.model");if(!model.contains("HTY-43F06B-VZ"))throw new IllegalStateException("Неподдерживаемый телевизор: "+model+". Изменения запрещены.");}
 private static boolean containsPkg(String list,String pkg){for(String s:list.split("\\r?\\n")) if(s.trim().equals("package:"+pkg))return true;return false;}
 String diagnostics()throws Exception {String model=shell("getprop ro.product.model");return "Модель: "+model+"\nAndroid: "+shell("getprop ro.build.version.release")+"\n\nХранилище:\n"+shell("df -h /data")+"\n\nПамять:\n"+shell("cat /proc/meminfo | head -n 5")+"\n\nВремя работы:\n"+shell("uptime")+"\n\nПользовательские приложения:\n"+shell("pm list packages -3")+"\n\nОтключённые приложения:\n"+shell("pm list packages -d");}
 String quick()throws Exception {guard();StringBuilder b=new StringBuilder("ТУРБО-ПРОФИЛЬ 0.25x\n");b.append(animations("0.25")).append("\n");b.append(disable(GAMES)).append("\n");b.append(disable(BUGS)).append("\n");b.append(cleanCache());return b.toString();}
 String animations(String value)throws Exception{guard();if(!("0.25".equals(value)||"0.5".equals(value)))throw new IllegalArgumentException("Недопустимый масштаб");StringBuilder b=new StringBuilder();for(String k:ANIM){String key=p("anim_"+k);if(!prefs.contains(key)){String before=shell("settings get global "+k);if(!before.matches("null|[0-9]+(\\.[0-9]+)?"))throw new IllegalStateException("Не удалось прочитать настройку "+k+": "+before);prefs.edit().putString(key,before).commit();}shell("settings put global "+k+" "+value);String actual=shell("settings get global "+k);if(!actual.equals(value)&&!actual.equals(value+"0"))throw new IllegalStateException("Настройка не подтвердилась: "+k+"="+actual);b.append(k).append(" = ").append(actual).append("\n");}return b.toString();}
 String cleanCache()throws Exception{guard();String before=shell("df -h /data");String response=shell("pm trim-caches 600M");String after=shell("df -h /data");return "Кэш очищен по запросу Android.\nДо:\n"+before+"\nПосле:\n"+after+(response.isEmpty()?"":"\n"+response);}
 String disable(String pkg)throws Exception{guard();if(!(pkg.equals(GAMES)||pkg.equals(BUGS)||pkg.equals(ADID)))throw new SecurityException("Недопустимый пакет");String all=shell("pm list packages --user 0");if(!containsPkg(all,pkg))return "Приложение не найдено: "+pkg;String disabled=shell("pm list packages -d --user 0");if(containsPkg(disabled,pkg))return "Уже отключено: "+pkg;String key=p("pkg_"+pkg);if(!prefs.contains(key))prefs.edit().putBoolean(key,true).commit();String response=shell("pm disable-user --user 0 "+pkg);if(!containsPkg(shell("pm list packages -d --user 0"),pkg))throw new IllegalStateException("Не удалось отключить "+pkg+"; "+response);return "Отключено: "+pkg;}
 String restore()throws Exception{guard();StringBuilder b=new StringBuilder("ОТКАТ ИЗМЕНЕНИЙ ЭТОЙ ВЕРСИИ\n");int n=0;for(String k:ANIM){String key=p("anim_"+k);if(!prefs.contains(key))continue;String v=prefs.getString(key,"null");if("null".equals(v))shell("settings delete global "+k);else if(v.matches("[0-9]+(\\.[0-9]+)?"))shell("settings put global "+k+" "+v);else throw new IllegalStateException("Некорректная резервная копия: "+k);String actual=shell("settings get global "+k);if(!actual.equals(v)&&!(actual.equals(v+".0")))throw new IllegalStateException("Ошибка восстановления "+k+"="+actual);prefs.edit().remove(key).commit();b.append(k).append(" → ").append(v).append("\n");n++;}
 for(String pkg:new String[]{GAMES,BUGS,ADID}){String key=p("pkg_"+pkg);if(!prefs.getBoolean(key,false))continue;String disabled=shell("pm list packages -d --user 0");if(containsPkg(disabled,pkg)){shell("pm enable --user 0 "+pkg);if(containsPkg(shell("pm list packages -d --user 0"),pkg))throw new IllegalStateException("Не удалось восстановить "+pkg);}prefs.edit().remove(key).commit();b.append("Восстановлено: ").append(pkg).append("\n");n++;}
 return b.append(n==0?"Изменений этой версии для отката нет.":"Шагов: "+n).toString();}
 String restoreOne(String pkg)throws Exception{guard();if(!(pkg.equals(GAMES)||pkg.equals(BUGS)||pkg.equals(ADID)))throw new SecurityException("Недопустимый пакет");String key=p("pkg_"+pkg);if(!prefs.getBoolean(key,false))return "Этот компонент не отключался этой версией. Для сохранности других настроек действий нет.";if(containsPkg(shell("pm list packages -d --user 0"),pkg)){shell("pm enable --user 0 "+pkg);if(containsPkg(shell("pm list packages -d --user 0"),pkg))throw new IllegalStateException("Пакет всё ещё отключён");}prefs.edit().remove(key).commit();return "Восстановлен "+pkg;}
 String status()throws Exception{String disabled=shell("pm list packages -d --user 0");return "Яндекс Игры: "+(containsPkg(disabled,GAMES)?"выключены":"включены")+"\nОтчёты об ошибках: "+(containsPkg(disabled,BUGS)?"выключены":"включены")+"\nРекламный идентификатор: "+(containsPkg(disabled,ADID)?"выключен":"включён")+"\n\nBluetooth, Wi-Fi, Алиса, пульт и лаунчер не меняются.";}
}
